class ShoppingCart:
    def __init__(self):
        self.lines = []

    def add(self, item, price, qty=1):
        self.lines.append((item, price, qty))

    def total(self):
        return round(sum(price * qty for item, price, qty in self.lines), 2)

    def item_count(self):
        return sum(qty for item, price, qty in self.lines)
